package ktanesolver.module.modded.regular.mahjong;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class MahjongSolverTest{private final MahjongSolver solver=new MahjongSolver();
	@Test void swapsFromSerialRotatesByCountingTileAndFindsAvailablePair(){ModuleEntity module=new ModuleEntity();MahjongOutput out=solve(module,new MahjongInput("Spring",List.of("Bamboo 2","Char 5","Char 1","Wheel 9"),0));assertThat(out.pair()).containsExactly("Bamboo 2","Char 5");assertThat(out.matchRow1()).containsExactly("Char 1","Bamboo 5","Wheel 7","Bamboo 8","Bamboo 2","Char 9","Red Dragon","Bamboo 6","Bamboo 4","Wheel 4","Wheel 3","Char 2","Wheel 1","Char 3");assertThat(out.matchRow2()).containsExactly("Bamboo 3","Wheel 8","Char 6","Wheel 6","Char 5","Wheel 9","Wheel 2","Char 8","Wheel 5","Bamboo 9","Bamboo 7","Char 7","White Dragon","Char 4");assertThat(module.getState().get("mahjongCountingTile")).isEqualTo("Spring");}
	@Test void onlyMarksSolvedWhenReturningFourteenthPair(){assertThat(result(new MahjongInput("Bamboo 1",List.of("Char 1","Wheel 9"),12))).isInstanceOfSatisfying(SolveSuccess.class,s->assertThat(((SolveSuccess<?>)s).solved()).isFalse());assertThat(result(new MahjongInput("Bamboo 1",List.of("Char 1","Wheel 9"),13))).isInstanceOfSatisfying(SolveSuccess.class,s->assertThat(((SolveSuccess<?>)s).solved()).isTrue());}
	@Test void validatesCountingAvailableAndSerialInputs(){assertThat(result(new MahjongInput("Wheel 1",List.of("Char 1","Wheel 9"),0))).isInstanceOf(SolveFailure.class);assertThat(result(new MahjongInput("Bamboo 1",List.of("Char 1","Char 1"),0))).isInstanceOf(SolveFailure.class);assertThat(result(new MahjongInput("Bamboo 1",List.of("Char 1","Bamboo 5"),0))).isInstanceOf(SolveFailure.class);}
	private SolveResult<MahjongOutput>result(MahjongInput input){BombEntity bomb=new BombEntity();bomb.setSerialNumber("ABC123");return solver.solve(new RoundEntity(),bomb,new ModuleEntity(),input);}@SuppressWarnings("unchecked")private MahjongOutput solve(ModuleEntity module,MahjongInput input){BombEntity bomb=new BombEntity();bomb.setSerialNumber("ABC123");return((SolveSuccess<MahjongOutput>)solver.solve(new RoundEntity(),bomb,module,input)).output();}}
